request:
{
 "project": "Gemini Software Requirements Specification",
 "meeting": "1 of 1 (kickoff)",
 "participants": [
  "Analyst",
  "Client",
  "EndUser",
  "TechLead"
 ],
 "previous_turns_for_context_only": [
  {
   "speaker": "EndUser",
   "act": "confirm"
  },
  {
   "speaker": "Analyst",
   "act": "ask_topic"
  },
  {
   "speaker": "Client",
   "act": "state",
   "content": [
    "Other astronomical information such as that coming from sky field monitors, autoguider cameras and sky monitoring devices such as cloud and seeing monitors shall also be capable of being available."
   ]
  }
 ],
 "turns": [
  {
   "id": "M1:T61",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'capacity' and asks about it."
  },
  {
   "id": "M1:T62",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Each node will have the capability to run at all operation levels.",
     "role": "statement"
    },
    {
     "text": "The system will provide for one auxiliary data acquisition and instrument control nodes.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T63",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "In addition, the system must support off-site observing modes.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T64",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T65",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "In practice the operation and facilities foreseen so far for the Gemini 8m Telescopes will limit this number to a maximum in the order of three active nodes, but the Gemini 8m Telescopes computers and software shall be capable of coping with the load of 10 active nodes, should the case arise",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T66",
   "speaker": "Analyst",
   "act": "anything_else",
   "guide": "Analyst asks whether there is anything else on 'capacity'."
  },
  {
   "id": "M1:T67",
   "speaker": "Client",
   "act": "nothing_else",
   "guide": "Short answer: nothing else on this topic."
  },
  {
   "id": "M1:T68",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'user interface (uif)' and asks about it."
  },
  {
   "id": "M1:T69",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The user interface should not be seen as a package linked to a specific computer.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T70",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The user interface tools shall be based on standards, defined in Section 4.2.5 on page 4- 7, which will be portable across different computer hardware platforms (Portable User Interface Toolkit).",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T71",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T72",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'hardware interface' and asks about it."
  },
  {
   "id": "M1:T73",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Standard interfaces to the control electronics shall be available, in the form of: standard bus systems; a standard set of interface cards to be used on all the subsystems and instruments; a standard software skeleton running on the control electronics.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T74",
   "speaker": "Analyst",
   "act": "anything_else",
   "guide": "Analyst asks whether there is anything else on 'hardware interface'."
  },
  {
   "id": "M1:T75",
   "speaker": "TechLead",
   "act": "nothing_else",
   "guide": "Short answer: nothing else on this topic."
  },
  {
   "id": "M1:T76",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'on-line image processing interfaces' and asks about it."
  },
  {
   "id": "M1:T77",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Quick-look data processing should be provided on the Gemini 8m Telescopes, with procedures suitable for fast on-line data preprocessing.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T78",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Near-line processing should be available for simple data reductions required for data integrity validation (i.e. remove instrument and observatory effects so the observer can make decisions about further observing actions).",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T79",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Off-line pixel processing for full data reduction should also exist at the Gemini 8m Telescopes site, but does not have any interface to the Gemini 8m Telescopes software.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T80",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  }
 ]
}
